BEGIN;
SET LOCAL lock_timeout='10s'; SET LOCAL statement_timeout='30s';
DO $integration$
DECLARE candidate text; manifest jsonb; rec jsonb; recid bigint; n int; ids jsonb;
BEGIN
PERFORM population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=85177 AND event='ENGINEERING_ASSIGNMENT_CLAIMED_V5' AND details->>'automation_run_id'='047b30e0-cc34-8331-bfbb-a6bcb5d56192' AND (details->>'expires_at')::timestamptz>clock_timestamp()) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event IN('ENGINEERING_ASSIGNMENT_COMPLETED_V5','ENGINEERING_ASSIGNMENT_EFFECTS_RECONCILED_RELEASE_V5') AND details->>'claim_event_id'='85177') THEN RAISE EXCEPTION 'CURRENT_CLAIM_REQUIRED';END IF;
IF (SELECT encode(sha256(convert_to(details::text,'UTF8')),'hex') FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=85170)<>'d5e34d496b1a362e4d99a26c3bebbc73849bbb33dcba6ebf7961861f10db228d' THEN RAISE EXCEPTION 'ASSIGNMENT_CHANGED';END IF;
IF population_top3000_202608_202609_v1.population_recovery_manifest_v1() IS DISTINCT FROM '{"functions":"6f9497e5470c33e1249b9865966af58df4019bc78ab6601a2e8e4ff8aacb811f","adapters":"1a746a4da2046b4af28a70be31da54a883de50ecae1a0f82c4386265d6cecbc2"}'::jsonb THEN RAISE EXCEPTION 'RECOVERY_PREIMAGE_CHANGED';END IF;
SELECT event_id,details INTO STRICT recid,rec FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='RECOVERY_DELEGATION_QUALIFIED_V1' ORDER BY event_id DESC LIMIT 1;
IF recid<>84927 OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_attempt WHERE ended_at IS NULL) THEN RAISE EXCEPTION 'ACTIVE_OR_RECOVERY_CHANGED';END IF;
IF to_regprocedure('population_top3000_202608_202609_v1.retained_price_stage_v3(uuid,text)') IS NOT NULL OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_adapter WHERE family_id='P02' AND stage IN('DERIVE','VALIDATE')) THEN RAISE EXCEPTION 'CANDIDATE_ALREADY_PRESENT';END IF;
IF encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.retained_price_normalize_v2(uuid,text)'::regprocedure),'UTF8')),'hex')<>'0c9caf459397b6e1ff65de27c1897af6b2865638cfd9c596bc8b67494ec9fd39' THEN RAISE EXCEPTION 'NORMALIZER_CHANGED';END IF;
SELECT details->>'candidate_sql' INTO STRICT candidate FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=85159;
IF encode(sha256(convert_to(candidate,'UTF8')),'hex')<>'b098c2868e861862f1aac2305c0d123e829e86eee72867314b9513b30e4f8e68' OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=85181 AND details->>'distinct_from_producer'='true' AND details->>'result'='APPROVED_FOR_EXACT_RETAINED_P02_ROUTE_WITH_CONDITIONS') THEN RAISE EXCEPTION 'EXACT_REVIEW_REQUIRED';END IF;
EXECUTE candidate;
IF encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.retained_price_stage_v3(uuid,text)'::regprocedure),'UTF8')),'hex')<>'2a7fb0045f183725b26f5ca9c0d4b1b8f3d5af29a820cecb84127016ca0efe5e' OR (SELECT prosecdef FROM pg_proc WHERE oid='population_top3000_202608_202609_v1.retained_price_stage_v3(uuid,text)'::regprocedure) OR has_function_privilege('anon','population_top3000_202608_202609_v1.retained_price_stage_v3(uuid,text)','EXECUTE') OR has_function_privilege('authenticated','population_top3000_202608_202609_v1.retained_price_stage_v3(uuid,text)','EXECUTE') THEN RAISE EXCEPTION 'EXACT_HASH_PRIVATE_INVOKER_REQUIRED';END IF;
INSERT INTO population_top3000_202608_202609_v1.pipeline_adapter(family_id,stage,function_oid,function_sha256,resource_class,provider,enabled,reviewed_test_evidence,producer_revision,expected_batch_seconds)
SELECT 'P02',s,'population_top3000_202608_202609_v1.retained_price_stage_v3(uuid,text)'::regprocedure::oid,'2a7fb0045f183725b26f5ca9c0d4b1b8f3d5af29a820cecb84127016ca0efe5e','DATABASE',NULL,true,jsonb_build_object('candidate_event_id',85159,'actual_rollback_proof_event_id',85169,'actual_test_count',21,'distinct_review_event_id',85181,'family_accepted',false),'RETAINED_PRICE_STAGE_V3',5 FROM unnest(ARRAY['DERIVE','VALIDATE'])s;
manifest:=population_top3000_202608_202609_v1.population_recovery_manifest_v1();
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('RECOVERY_DELEGATION_QUALIFIED_V1',rec||jsonb_build_object('prior_recovery_event_id',recid,'code_requalified_at',clock_timestamp(),'code_manifest',manifest,'code_manifest_sha256',encode(sha256(convert_to(manifest::text,'UTF8')),'hex'),'reviewed_manifest_sha256',encode(sha256(convert_to(manifest::text,'UTF8')),'hex'),'retained_price_stage_v3_binding',jsonb_build_object('claim_event_id',85177,'review_event_id',85181,'proof_event_id',85169,'source_calls',0,'family_accepted',false))) RETURNING event_id INTO recid;
WITH eligible AS MATERIALIZED(SELECT t.task_id FROM population_top3000_202608_202609_v1.pipeline_task t WHERE t.family_id='P02' AND t.stage='DERIVE' AND t.status='BLOCKED' AND t.blocker_code='ADAPTER_NOT_INSTALLED' AND t.payload->>'normalization_route'='RETAINED_PRICE_NORMALIZE_V2' AND t.payload->>'kind'='RETAINED_ALPACA_AUGUST_SESSION' AND t.payload->>'session_label'='premarket' AND t.lease_until IS NULL AND EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_dependency d JOIN population_top3000_202608_202609_v1.pipeline_task p ON p.task_id=d.prerequisite_task_id WHERE d.task_id=t.task_id AND p.status='COMPLETE' AND p.stage='NORMALIZE' AND p.family_id=t.family_id AND p.partition_key=t.partition_key AND p.input_versions=t.input_versions)), upd AS(UPDATE population_top3000_202608_202609_v1.pipeline_task t SET status='READY',blocker_code=NULL,resumption_condition=NULL,blocker_until=NULL,not_before=clock_timestamp() FROM eligible e WHERE t.task_id=e.task_id RETURNING t.task_id) SELECT count(*),jsonb_agg(task_id ORDER BY task_id) INTO n,ids FROM upd;
IF n<>64 THEN RAISE EXCEPTION 'EXACT_64_EXPECTED_GOT_%',n;END IF;
UPDATE population_top3000_202608_202609_v1.pipeline_control SET next_wakeup_at=clock_timestamp(),wake_reason='REVIEWED_P02_STAGE_V3_READY' WHERE singleton AND wake_reason='WAIT_FOR_READY_TASK_OR_EVIDENCE';
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('RETAINED_PRICE_STAGE_V3_INTEGRATED',jsonb_build_object('assignment_event_id',85170,'claim_event_id',85177,'review_event_id',85181,'proof_event_id',85169,'candidate_event_id',85159,'recovery_event_id',recid,'code_manifest',manifest,'requeued_tasks',ids,'requeued_count',n,'new_functions',1,'new_adapters',2,'source_calls',0,'family_accepted',false,'run_id','047b30e0-cc34-8331-bfbb-a6bcb5d56192'));
END $integration$;
COMMIT;